207: // Flat fp32 master update with in-register unscaling and low-precision
208: // writeback. No optimizer state is kept in the low-precision output.
209: template <typename Output>
210: __global__ void mixed_precision_adam_kernel(const float* g,
211:                                             float* p,
212:                                             float* m,
213:                                             float* v,
214:                                             Output* output,
215:                                             int64_t n,
216:                                             float beta1,
217:                                             float beta2,
218:                                             float correction1,
219:                                             float correction2,
220:                                             float epsilon,
221:                                             float lr,
222:                                             int mode,
223:                                             float decay,
224:                                             float inv_scale)
225: {
226:     for (int64_t start = (int64_t)blockIdx.x * blockDim.x * 4;
227:          start < n;
228:          start += (int64_t)gridDim.x * blockDim.x * 4) {
229:         float rg[4], rp[4], rm[4], rv[4];
230: #pragma unroll
231:         for (int j = 0; j < 4; ++j) {
232:             int64_t i = start + threadIdx.x + j * blockDim.x;
233:             if (i < n) {
234:                 // Match the rounding of the original standalone fp32 mul_.
235:                 rg[j] = __fmul_rn(g[i], inv_scale);
236:                 rp[j] = p[i];
237:                 rm[j] = m[i];
238:                 rv[j] = v[i];
239:             } else {
240:                 rg[j] = rp[j] = rm[j] = rv[j] = 0.0f;
241:             }
242:         }
243: #pragma unroll
244:         for (int j = 0; j < 4; ++j) {
245:             if (mode == ADAM_MODE_0) {
246:                 rg[j] = rg[j] + decay * rp[j];
247:                 rm[j] = beta1 * rm[j] + (1 - beta1) * rg[j];
248:                 rv[j] = beta2 * rv[j] + (1 - beta2) * rg[j] * rg[j];
249:                 float next_m = rm[j] / correction1;
250:                 float next_v = rv[j] / correction2;
251:                 float denom = sqrtf(next_v) + epsilon;
252:                 float update = next_m / denom;
253:                 rp[j] = rp[j] - lr * update;
