255:                 rm[j] = beta1 * rm[j] + (1 - beta1) * rg[j];
256:                 rv[j] = beta2 * rv[j] + (1 - beta2) * rg[j] * rg[j];
257:                 float next_m = rm[j] / correction1;
258:                 float next_v = rv[j] / correction2;
